@Log4j2
public class TokenAuthenticationFilter implements WebFilter {

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, WebFilterChain chain) {
        log.debug("-->TokenAuthenticationFilter");
        log.debug("\tRequested URI Path: \n\t{}", exchange.getRequest().getURI().getPath());
        log.debug("\texisting cookies: \n\t{}", new ArrayList<>(exchange.getRequest().getCookies().entrySet()).stream().map(stringListEntry -> "\n\t" + stringListEntry.getValue() + "\n").collect(Collectors.toList()));

        MultiValueMap<String, HttpCookie> cookies = exchange.getRequest().getCookies();
        ServerHttpRequest request = exchange.getRequest().mutate().headers(httpHeaders -> {
            if (!cookies.isEmpty()) {
                List<HttpCookie> cookie = cookies.get(SecurityConfig.ACCESS_TOKEN_COOKIE_NAME);
                if (cookie != null && cookie.size() == 1) {
                    String token = cookie.get(0).getValue();
                    httpHeaders.add(SecurityConfig.AUTHORIZATION_HEADER_NAME, "Bearer " + token);
                }
            }
        }).build();
        log.debug("\tadded headers: " + new ArrayList<>(exchange.getRequest().getHeaders().entrySet()).stream().map(entry -> "\n\t" + entry.getValue() + "\n").collect(Collectors.toList()));
        return chain.filter(exchange.mutate().request(request).build());
    }
}
    public Mono<Void> filter(ServerWebExchange exchange, WebFilterChain chain) {
        return chain.filter(exchange).doOnEach(signal -> {
            if (signal.isOnComplete() || signal.isOnError()) {
                try {
                    log.info("\n:: Request Log ::");
                    log.info("Request id: {}", exchange.getRequest().getId());
                    log.info("Ip: {}", exchange.getRequest().getRemoteAddress());
                    log.info("Method: {}", exchange.getRequest().getMethod());
                    log.info("Path: {}", exchange.getRequest().getURI());
                    // Use ArrayList copy to avoid ConcurrentModificationException / FixedNodeBuilder
                    // crash during WebSocket upgrade when headers are modified concurrently
                    log.info("Request Headers: {}", new ArrayList<>(exchange.getRequest()
                            .getHeaders()
                            .entrySet()));
                    log.info("Response: {}", exchange.getResponse().getStatusCode());
                    log.info("Response Headers: {}", new ArrayList<>(exchange.getResponse()
                            .getHeaders()
                            .entrySet()));
                    log.info("\n:: End Request Log ::");
                } catch (Exception e) {
                    log.warn("Could not log request/response details: {}", e.getMessage());
                }
            }
        });
    }

    @Override
    public int getOrder() {
        return SecurityWebFiltersOrder.FIRST.getOrder();
    }
}

